#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int cmpNumDesc(const void *pa, const void *pb) {
    const char *a = *(const char **)pa, *b = *(const char **)pb;
    size_t la = strlen(a), lb = strlen(b);
    if (la != lb) return la < lb ? 1 : -1;
    return strcmp(b, a);
}

char *kthLargestNumber(char **nums, int numsSize, int k) {
    qsort(nums, numsSize, sizeof(char *), cmpNumDesc);
    return nums[k - 1];
}

int main(void) {
    char *line = NULL;
    size_t cap = 0;
    if (getline(&line, &cap, stdin) == -1) return 0;
    char **nums = malloc(10000 * sizeof(char *));
    int n = 0;

    char *p = strchr(line, '[');
    if (!p) return 1;
    ++p;
    if (*p == '[') ++p;

    while (*p && *p != ']') {
        while (*p == ' ' || *p == ',') ++p;
        if (*p == ']') break;
        if (*p != '"') return 1;
        ++p;
        char *start = p;
        while (*p && *p != '"') ++p;
        size_t len = (size_t)(p - start);
        nums[n] = malloc(len + 1);
        memcpy(nums[n], start, len);
        nums[n][len] = '\0';
        ++n;
        if (*p == '"') ++p;
    }

    p = strchr(p, ',');
    if (!p) return 1;
    int k = atoi(p + 1);

    char *ans = kthLargestNumber(nums, n, k);
    printf("\"%s\"\n", ans);

    for (int i = 0; i < n; ++i) free(nums[i]);
    free(nums);
    free(line);
    return 0;
}

