using namespace std;

class Solution {
public:
    string kthLargestNumber(vector<string>& nums, int k) {
        sort(nums.begin(), nums.end(), [](const string& a, const string& b) {
            if (a.size() != b.size()) return a.size() > b.size();
            return a > b;
        });
        return nums[k - 1];
    }
};

int main() {
    string line;
    getline(cin, line);
    vector<string> nums;
    size_t p = line.find('[', 1) + 1;
    while (p < line.size() && line[p] != ']') {
        while (p < line.size() && (line[p] == ' ' || line[p] == ',' || line[p] == '[')) ++p;
        if (p >= line.size() || line[p] == ']') break;
        ++p;
        string s;
        while (line[p] != '"') s += line[p++];
        ++p;
        nums.push_back(s);
    }
    p = line.find(',', p) + 1;
    int k = stoi(line.substr(p, line.find(']', p) - p));
    cout << '"' << Solution().kthLargestNumber(nums, k) << '"' << '\n';
}

