import java.io.*;
import java.util.*;

class Solution {
    public String kthLargestNumber(String[] nums, int k) {
        String[] a = nums.clone();
        Arrays.sort(a, (x, y) -> {
            if (x.length() != y.length()) return Integer.compare(y.length(), x.length());
            return y.compareTo(x);
        });
        return a[k - 1];
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        int p = line.indexOf('[') + 1;
        List<String> nums = new ArrayList<>();
        while (p < line.length() && line.charAt(p) != ']') {
            while (p < line.length() && (line.charAt(p) == ' ' || line.charAt(p) == ',' || line.charAt(p) == '[')) p++;
            if (p >= line.length() || line.charAt(p) == ']') break;
            p++; // opening quote
            StringBuilder sb = new StringBuilder();
            while (line.charAt(p) != '"') sb.append(line.charAt(p++));
            p++; // closing quote
            nums.add(sb.toString());
        }
        while (p < line.length() && line.charAt(p) != ',') p++;
        p++;
        int end = line.lastIndexOf(']');
        int k = Integer.parseInt(line.substring(p, end).trim());
        String result = new Solution().kthLargestNumber(nums.toArray(new String[0]), k);
        System.out.println("\"" + result + "\"");
    }
}

